import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import "./AdminNotification.css";
import AdminSidebar from "../components/AdminSideBar";

const AdminNotificationsPage = () => {
  const [notifications, setNotifications] = useState([]);
  const [newNotification, setNewNotification] = useState('');
  const [scheduledDate, setScheduledDate] = useState('');
  const [scheduledTime, setScheduledTime] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');

  // Fetch notifications on page load
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const response = await axios.get("http://localhost:5000/api/notification");
        setNotifications(response.data);
      } catch (error) {
        console.error("Failed to fetch notifications:", error);
      }
    };
    fetchNotifications();
  }, []);

  // Mark a notification as read
  const markAsRead = (id) => {
    setNotifications(
      notifications.map((notification) =>
        notification.id === id ? { ...notification, isRead: true } : notification
      )
    );
  };

  // Delete a notification
  const deleteNotification = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/notification/${id}`);
      setNotifications(notifications.filter((notification) => notification.id !== id));
    } catch (error) {
      console.error("Delete Error:", error.response?.data || error.message);
      alert("Failed to delete notification.");
    }
  };

  // Handle form submission for adding a new notification
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (newNotification.trim() !== "" && scheduledDate && scheduledTime) {
      setIsSubmitting(true);
      setSuccessMessage('');

      const scheduledDateTime = new Date(`${scheduledDate}T${scheduledTime}`);
      const currentDateTime = new Date();

      const formattedDate = currentDateTime.toLocaleDateString();
      const formattedTime = currentDateTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      const newNotificationObj = {
        message: newNotification,
        date: formattedDate,
        time: formattedTime,
        isRead: false
      };

      const sendNotification = async () => {
        try {
          const res = await axios.post("http://localhost:5000/api/notification", newNotificationObj);
          const createdNotification = res.data;
          setNotifications([createdNotification, ...notifications]);
          setSuccessMessage("Notification has been sent successfully!");
        } catch (error) {
          console.error("Failed to send notification:", error);
          alert("Failed to send notification.");
        } finally {
          setIsSubmitting(false);
          setNewNotification('');
          setScheduledDate('');
          setScheduledTime('');
        }
      };

      if (scheduledDateTime > currentDateTime) {
        const delay = scheduledDateTime - currentDateTime;
        setTimeout(sendNotification, delay);
      } else {
        await sendNotification();
      }
    } else {
      alert("Please provide a message, date, and time for the notification.");
      setIsSubmitting(false);
    }
  };

  return (
    <div className="proposal-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />

        <div className="admin-notifications-container">
          <header className="header">
            <h1>Admin Notifications</h1>
            <p>View, manage, and send notifications to students and supervisors</p>
          </header>

          <div className="notification-form-container">
            <h2>Create New Notification</h2>
            <form onSubmit={handleSubmit}>
              <textarea
                value={newNotification}
                onChange={(e) => setNewNotification(e.target.value)}
                placeholder="Write your notification here..."
                rows="4"
                required
              />
              <div className="form-actions">
                <label>
                  Schedule Date:
                  <input
                    type="date"
                    value={scheduledDate}
                    onChange={(e) => setScheduledDate(e.target.value)}
                    required
                  />
                </label>
                <label>
                  Schedule Time:
                  <input
                    type="time"
                    value={scheduledTime}
                    onChange={(e) => setScheduledTime(e.target.value)}
                    required
                  />
                </label>
                <button type="submit" className="btn submit" disabled={isSubmitting}>
                  {isSubmitting ? "Submitting..." : "Submit Notification"}
                </button>
              </div>
            </form>
            {successMessage && <p className="success-message">{successMessage}</p>}
          </div>

          <div className="notifications-list">
            <h2>Recent Notifications</h2>
            {notifications.length > 0 ? (
              <ul>
                {notifications.map((notification) => (
                  <li key={notification.id} className={`notification-item ${notification.isRead ? "read" : "unread"}`}>
                    <div>
                      <p className="notification-message">{notification.message}</p>
                      <p className="notification-date">{`${notification.date} at ${notification.time}`}</p>
                    </div>
                    <div className="notification-actions">
                      {!notification.isRead && (
                        <button className="btn mark-as-read" onClick={() => markAsRead(notification.id)}>
                          Mark as Read
                        </button>
                      )}
                      <button className="btn delete" onClick={() => deleteNotification(notification.id)}>
                        Delete
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <p>No notifications available.</p>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default AdminNotificationsPage;
